engine.analyze:
async function analyze(input, providers) {
  // ── Local helpers (closure-scoped to satisfy the bundler) ────────────
  function _validateErrorData(data) {
    if (!Array.isArray(data)) return [];
    return data.filter(function (item) {
      return item && item.original && item.correction;
    });
  }
  function _stripHtmlTags(html) {
    if (!html) return "";
    return String(html)
      .replace(/<[^>]+>/g, " ")
      .replace(/&nbsp;/g, " ")
      .replace(/&amp;/g, "&")
      .replace(/&lt;/g, "<")
      .replace(/&gt;/g, ">")
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/\s+/g, " ")
      .trim();
  }
  function _normalizeWhitespace(text) {
    if (!text) return "";
    return String(text).replace(/\s+/g, " ").trim();
  }
  function _buildResult(items, warnings, totalWords, settings, input, overview) {
    return {
      items: items,
      warnings: warnings,
      totalWords: totalWords,
      overview: overview,
      provenance: {
        kernelVersion: (typeof window !== "undefined" && window.eli)
          ? window.eli.kernelVersion : "node",
        toolVersion: "1.0.0",
        promptVersion: "errorCheck@v16",
        model: (typeof window !== "undefined" && window.eli && window.eli.ai &&
                typeof window.eli.ai.getModel === "function")
          ? window.eli.ai.getModel() : null,
        timestamp: Date.now(),
        docHash: input && input.docHash || null,
        settings: settings,
      },
    };
  }

  var settings = (input && input.settings) || {};
  var onLog = (input && typeof input.onLog === "function") ? input.onLog : function () { };
  var sensitivity = settings.sensitivity || "Balanced";
  var scope = settings.scope === "selection" ? "selection" : "full";
  var prefix = "_ELI_ER_";

  onLog({ kind: "step", id: "extract", icon: "⏳",
    text: scope === "selection" ? "Extracting selected paragraphs..." : "Extracting paragraphs..." });

  // ── Step 1: Extract paragraphs + insert per-paragraph bookmarks ──────
  // Bookmarks let the report's "Locate" button jump straight to the
  // exact paragraph instead of doing a brittle search-by-text. Mirrors
  // v2's getLegalTextWithAnchors. Sweeps any leftover _ELI_ER_* bookmarks
  // first so they don't accumulate across re-scans.
  var extracted = await providers.host.runRaw("error_review:extract", function (context) {
    var bks = context.document.body.getRange().bookmarks;
    bks.load("items");
    return context.sync().then(function () {
      bks.items.forEach(function (b) {
        if (b && b.name && b.name.indexOf(prefix) === 0) {
          try { b.delete(); } catch (e) { /* tolerate */ }
        }
      });
      return context.sync();
    }).then(function () {
      // Honor scope: "selection" reads the user's highlighted range only;
      // "full" walks the entire body. Selection still emits bookmarks for
      // Locate to work — they're scoped to within the selection range.
      var scopedRange = scope === "selection"
        ? context.document.getSelection()
        : context.document.body;
      var paragraphs = scopedRange.paragraphs;
      paragraphs.load("items");
      return context.sync().then(function () {
        for (var i = 0; i < paragraphs.items.length; i++) {
          paragraphs.items[i].load("text");
        }
        return context.sync();
      }).then(function () {
        var payloadArr = [];
        var fullText = "";
        for (var i = 0; i < paragraphs.items.length; i++) {
          var p = paragraphs.items[i];
          var t = _normalizeWhitespace(p.text || "");
          fullText += t + "\n";
          if (t.length > 5) {
            var bName = prefix + i;
            try { p.getRange().insertBookmark(bName); } catch (e) { /* tolerate */ }
            payloadArr.push({ id: bName, text: t });
          }
        }
        return context.sync().then(function () {
          return {
            payloadJSON: JSON.stringify(payloadArr),
            paragraphCount: payloadArr.length,
            fullText: fullText,
          };
        });
      });
    });
  });

  if (extracted.paragraphCount === 0) {
    onLog({ kind: "step", id: "extract", icon: "⚠️", text: "No paragraphs to scan.", warn: true });
    return _buildResult([], [], 0, settings, input, "Document is empty.");
  }

  onLog({
    kind: "step", id: "extract", icon: "📑",
    text: "Extracted " + extracted.paragraphCount + " paragraph(s)",
  });

  // ── Step 2: Footer consistency check (CP Ref / A-NNN matching) ───────
  // Walks every Primary/FirstPage/EvenPages footer across all sections,
  // pulls a CP Ref or A-NNN from page-1, then flags mismatched ones.
  // Mirrors v2's checkFooterConsistency. Independent of AI; runs in
  // parallel with the AI scan below.
  onLog({ kind: "step", id: "footer", icon: "⏳", text: "Checking footer consistency..." });
  var footerErrorsPromise = providers.host.runRaw("error_review:footers", function (context) {
    var sections = context.document.sections;
    sections.load("items");
    return context.sync().then(function () {
      var footerRanges = [];
      sections.items.forEach(function (section, index) {
        ["Primary", "FirstPage", "EvenPages"].forEach(function (type) {
          try {
            var f = section.getFooter ? section.getFooter(type) : section.footers.getItem(type);
            var r = f.getRange();
            var h = r.getHtml();
            footerRanges.push({ type: type, section: index + 1, html: h });
          } catch (e) { /* type not present in this section */ }
        });
      });
      return context.sync().then(function () {
        var errors = [];
        var refRegex = /(CP Ref:|A-)\s*([A-Za-z0-9\-]+)/i;
        function getText(item) {
          if (!item || !item.html) return "";
          return _stripHtmlTags(item.html.value || "");
        }
        var p1First = footerRanges.find(function (r) {
          return r.section === 1 && r.type === "FirstPage" && getText(r).trim().length > 0;
        });
        var p1Prim = footerRanges.find(function (r) {
          return r.section === 1 && r.type === "Primary" && getText(r).trim().length > 0;
        });
        var masterText = p1First ? getText(p1First) : (p1Prim ? getText(p1Prim) : "");
        var masterMatch = masterText.match(refRegex);
        if (!masterMatch) return [];
        var masterRef = masterMatch[0].trim();
        footerRanges.forEach(function (item) {
          var text = getText(item);
          if (text && text.trim().length > 0) {
            var match = text.match(refRegex);
            if (match) {
              var found = match[0].trim();
              if (found !== masterRef) {
                errors.push({
                  id: prefix + "footer_" + item.section + "_" + item.type,
                  original: found,
                  correction: masterRef,
                  reason: "Footer Mismatch: Section " + item.section + " (" + item.type +
                    ") has '" + found + "', but Page 1 is '" + masterRef + "'.",
                  error_type: "Consistency",
                  source: "footer",
                });
              }
            }
          }
        });
        return errors;
      });
    });
  }).catch(function (e) {
    return [{
      id: prefix + "footer_err",
      original: "Script Error",
      correction: "Footer Check",
      reason: "Footer-check logic error: " + (e && e.message || "unknown"),
      error_type: "System",
      source: "footer",
    }];
  });

  // ── Step 3: AI scan ──────────────────────────────────────────────────
  onLog({ kind: "step", id: "ai", icon: "⏳", text: "Sending to AI (sensitivity: " + sensitivity + ")..." });
  var aiErrorsPromise = (async function () {
    var promptRow = await providers.storage.get("prompts", "errorCheck");
    if (!promptRow || !promptRow.text) {
      throw new Error("Prompt template 'errorCheck' not in storage. Re-sync data bundles.");
    }

    // Build sensitivity-driven instructions block (v2 line 6280-6291).
    var instructions =
      "TASK 1: GRAMMAR, SPELLING & PUNCTUATION\n" +
      "Identify ALL grammatical errors, spelling mistakes, punctuation issues, " +
      "and awkward phrasing.\n" +
      "MISSING PUNCTUATION IS A TOP PRIORITY. Flag every instance of missing " +
      "punctuation including: missing periods at the end of sentences or " +
      "clauses, missing commas in addresses (city, state), lists, after " +
      "introductory clauses, and around appositives, missing semicolons " +
      "between independent clauses, and missing colons before lists.\n" +
      "Scan every sentence boundary. If a sentence or clause ends without a " +
      "period, question mark, or other required terminal punctuation, flag it.\n";
    if (sensitivity === "Picky") {
      instructions += "\nTASK 3: DEFINITION X-RAY\nScan for Capitalized words " +
        "not defined in the text.\n";
    }
    instructions += "\nIMPORTANT: Enforce US spelling. Flag UK spellings.\n";

    // Cross-reference is intentionally disabled — see v2 line 6282-6288.
    var sectionIndexBlock =
      "\n\nCROSS-REFERENCE CHECK IS DISABLED — do NOT flag any Cross-Ref " +
      "errors regardless of the instruction above.";

    var thinkingBudgetMap = { Essential: 0, Balanced: 4096, Picky: 8192 };
    var thinkBudget = thinkingBudgetMap[sensitivity] != null
      ? thinkingBudgetMap[sensitivity] : 4096;

    var prompt = providers.ai.formatPrompt(promptRow.text, {
      instructionsBlock: instructions ? instructions + "\n" : "",
      sectionIndexBlock: sectionIndexBlock,
      text: extracted.payloadJSON,
    });

    var rawData = await providers.ai.completeJSON(prompt, null, {
      thinkingBudget: thinkBudget,
    });

    // v2-format compat (line 6299-6303).
    if (Array.isArray(rawData)) {
      rawData.forEach(function (r) {
        if (r.exact_error && !r.original) r.original = r.exact_error;
        if (r.exact_fix && !r.correction) r.correction = r.exact_fix;
        r.source = r.source || "ai";
      });
    }
    return _validateErrorData(rawData);
  })();

  // ── Step 4: Combine + sort ───────────────────────────────────────────
  var combined = await Promise.all([aiErrorsPromise, footerErrorsPromise]);
  var aiErrors = combined[0] || [];
  var footerErrors = combined[1] || [];
  var allErrors = footerErrors.concat(aiErrors);

  allErrors.sort(function (a, b) {
    var na = parseInt(((a.id || "").match(/\d+$/) || [0])[0]) || 0;
    var nb = parseInt(((b.id || "").match(/\d+$/) || [0])[0]) || 0;
    return na - nb;
  });

  onLog({
    kind: "step", id: "done", icon: allErrors.length === 0 ? "✅" : "🔍",
    text: allErrors.length === 0
      ? "No errors found"
      : allErrors.length + " error(s) detected",
  });

  var totalWords = (extracted.fullText || "")
    .split(/\s+/)
    .filter(function (w) { return w.length > 0; }).length;

  return _buildResult(allErrors, [], totalWords, settings, input,
    allErrors.length === 0
      ? "Document passed all checks."
      : allErrors.length + " issue(s) detected (" +
        aiErrors.length + " from AI, " + footerErrors.length + " footer)."
  );
}

view.renderSettingsDialog:
function renderSettingsDialog(opts) {
  function _sensCard(value, badge, desc, checked) {
    return '<label class="_eli3_er_sens_card' + (checked ? " _eli3_er_sens_card_active" : "") + '">' +
      '<input type="radio" name="_eli3_er_sens" value="' + value + '"' +
        (checked ? " checked" : "") + ' class="_eli3_er_sens_input">' +
      '<div class="_eli3_er_sens_head">' +
        '<span class="_eli3_er_sens_name">' + value + '</span>' +
        '<span class="_eli3_er_sens_badge">' + badge + '</span>' +
      '</div>' +
      '<div class="_eli3_er_sens_desc">' + desc + '</div>' +
    '</label>';
  }

  opts = opts || {};
  var savedSensitivity = opts.sensitivity || "Balanced";
  var mount = opts.mount || document.getElementById("_eli3_dashboard_root");
  if (!mount) return Promise.resolve(null);

  return new Promise(function (resolve) {
    mount.innerHTML = "";
    var panel = document.createElement("div");
    panel.className = "_eli3_ds_panel";
    panel.innerHTML =
      '<div class="_eli3_ds_header">' +
        '<div class="_eli3_ds_header_eyebrow">PROOFREAD</div>' +
        '<div class="_eli3_ds_header_title"><span>🔍</span> Error Review · Settings</div>' +
      '</div>' +
      '<div class="_eli3_ds_body">' +
        '<p class="_eli3_ds_intro">' +
          'Choose how aggressive the AI should be. Saves apply to future scans.' +
        '</p>' +
        '<div class="_eli3_ds_eyebrow_blue">🎚️ Sensitivity</div>' +
        '<div class="_eli3_er_sens_grid">' +
          _sensCard("Essential", "Fast",
            "Periods, double spaces, obvious typos. ~30s.",
            savedSensitivity === "Essential") +
          _sensCard("Balanced", "Default",
            "Adds grammar + US spelling enforcement. ~60s.",
            savedSensitivity === "Balanced") +
          _sensCard("Picky", "Strict",
            "Adds undefined-capitalized-term scan. ~90s.",
            savedSensitivity === "Picky") +
        '</div>' +
        '<div class="_eli3_ds_run_row">' +
          '<button id="_eli3_er_cancel" class="_eli3_er_btn _eli3_er_btn_secondary">Cancel</button>' +
          '<button id="_eli3_er_save" class="_eli3_er_btn _eli3_er_btn_primary">Save</button>' +
        '</div>' +
      '</div>';
    mount.appendChild(panel);

    function _selected() {
      var picked = panel.querySelector('input[name="_eli3_er_sens"]:checked');
      return picked ? picked.value : "Balanced";
    }
    panel.querySelector("#_eli3_er_cancel").onclick = function () { resolve(null); };
    panel.querySelector("#_eli3_er_save").onclick = function () {
      resolve({ sensitivity: _selected() });
    };

    // Click-anywhere-on-card selects the radio.
    Array.prototype.forEach.call(
      panel.querySelectorAll("._eli3_er_sens_card"),
      function (card) {
        card.addEventListener("click", function () {
          Array.prototype.forEach.call(
            panel.querySelectorAll("._eli3_er_sens_card"),
            function (c) { c.classList.remove("_eli3_er_sens_card_active"); }
          );
          card.classList.add("_eli3_er_sens_card_active");
        });
      }
    );
  });
}

// ── Progress overlay (v2's robot loader) ─────────────────────────────
// Builds the same DOM v2 used (taskpane_v2.js setLoading line 13164):
// .robot-loader > .robot-head > .robot-eyes + .mouth-container with
// teeth + brush + foam. CSS for these classes lives in taskpane.css
// (carried over from v2). Caller gets {log, close}; log() updates the
// rotating message text, close() removes the overlay.

view.renderProgressOverlay:
function renderProgressOverlay() {
  var ov = document.createElement("div");
  ov.id = "_eli3_er_progress";
  ov.className = "_eli3_ds_progress"; // shared full-screen modal shell
  ov.innerHTML =
    '<div class="loading-card robot-loader" style="background:transparent;border:none;box-shadow:none;padding:10px 0;">' +
      '<div class="robot-head">' +
        '<div class="robot-eyes">' +
          '<div class="robot-eye"></div><div class="robot-eye"></div>' +
        '</div>' +
        '<div class="mouth-container">' +
          '<div class="teeth-row upper">' +
            '<div class="tooth"></div><div class="tooth"></div><div class="tooth"></div>' +
            '<div class="tooth"></div><div class="tooth"></div><div class="tooth"></div>' +
            '<div class="tooth"></div>' +
          '</div>' +
          '<div class="teeth-row lower">' +
            '<div class="tooth"></div><div class="tooth"></div><div class="tooth"></div>' +
            '<div class="tooth"></div><div class="tooth"></div><div class="tooth"></div>' +
            '<div class="tooth"></div>' +
          '</div>' +
          '<div class="brush-anim">🪥</div>' +
          '<div class="foam f1"></div><div class="foam f2"></div><div class="foam f3"></div>' +
        '</div>' +
      '</div>' +
      '<p class="loading-text" id="_eli3_er_loadertext" ' +
        'style="margin-top:18px;font-weight:700;color:#1565c0;font-size:13px;text-align:center">' +
        'Scanning…' +
      '</p>' +
    '</div>';
  document.body.appendChild(ov);

  // Rotate through encouraging messages every 1.5s while the AI runs
  // (matches v2 behaviour). Cleared on close.
  var msgs = [
    "Scanning…",
    "Reading every paragraph…",
    "Checking grammar…",
    "Hunting punctuation gaps…",
    "Cross-checking footers…",
    "Almost there…",
  ];
  var idx = 0;
  var textEl = ov.querySelector("#_eli3_er_loadertext");
  var rotator = setInterval(function () {
    idx = (idx + 1) % msgs.length;
    if (textEl) textEl.textContent = msgs[idx];
  }, 1500);

  function close() {
    clearInterval(rotator);
    if (ov.parentNode) ov.parentNode.removeChild(ov);
  }
  function log(entry) {
    // Engine emits step events. We treat them as opportunities to advance
    // the rotating text faster (the regular interval still runs).
    if (!textEl || !entry) return;
    if (entry.kind === "step" && entry.text) {
      textEl.textContent = entry.text;
    }
  }
  return { close: close, log: log };
}

// ── Report panel ─────────────────────────────────────────────────────
// Single header that includes the count: "Error Review · 7 Fixes Found".
// No HOME button. No re-scan button. No second banner.
// Cards use inline word-level diff: deletions in red strikethrough,
// additions in blue bold. Action buttons: Locate, Accept, Skip.

view.renderReportDialog:
function renderReportDialog(opts) {
  function _esc(s) {
    return String(s == null ? "" : s)
      .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;").replace(/'/g, "&#39;");
  }

  // Word-level diff (LCS-based, jsdiff-free). Returns array of hunks:
  //   { type: "equal", words: [...] }
  //   { type: "del",   words: [...] }
  //   { type: "add",   words: [...] }
  // Algorithm: classic dynamic-programming longest-common-subsequence.
  // Tokenize on whitespace. For text up to a few hundred words this is
  // O(n*m) which is fine — error excerpts are usually < 30 words each.
  function _wordDiff(oldText, newText) {
    var a = String(oldText || "").split(/(\s+)/).filter(function (s) { return s.length > 0; });
    var b = String(newText || "").split(/(\s+)/).filter(function (s) { return s.length > 0; });
    var m = a.length, n = b.length;
    // Build LCS length table.
    var dp = [];
    for (var i = 0; i <= m; i++) {
      dp.push(new Array(n + 1).fill(0));
    }
    for (var i = 1; i <= m; i++) {
      for (var j = 1; j <= n; j++) {
        if (a[i - 1] === b[j - 1]) dp[i][j] = dp[i - 1][j - 1] + 1;
        else dp[i][j] = Math.max(dp[i - 1][j], dp[i][j - 1]);
      }
    }
    // Backtrack to produce hunks.
    var ops = [];
    var i2 = m, j2 = n;
    while (i2 > 0 || j2 > 0) {
      if (i2 > 0 && j2 > 0 && a[i2 - 1] === b[j2 - 1]) {
        ops.unshift({ type: "equal", word: a[i2 - 1] });
        i2--; j2--;
      } else if (j2 > 0 && (i2 === 0 || dp[i2][j2 - 1] >= dp[i2 - 1][j2])) {
        ops.unshift({ type: "add", word: b[j2 - 1] });
        j2--;
      } else if (i2 > 0) {
        ops.unshift({ type: "del", word: a[i2 - 1] });
        i2--;
      }
    }
    // Coalesce consecutive ops of the same type.
    var hunks = [];
    ops.forEach(function (op) {
      var last = hunks[hunks.length - 1];
      if (last && last.type === op.type) last.words.push(op.word);
      else hunks.push({ type: op.type, words: [op.word] });
    });
    return hunks;
  }

  // Render the inline diff as HTML. Equal = plain, del = red strike,
  // add = blue bold.
  function _renderDiff(originalText, fixText) {
    var hunks = _wordDiff(originalText, fixText);
    var html = "";
    hunks.forEach(function (h) {
      var text = h.words.join("");
      if (h.type === "equal") {
        html += _esc(text);
      } else if (h.type === "del") {
        html += '<span class="_eli3_er_diff_del">' + _esc(text) + '</span>';
      } else if (h.type === "add") {
        html += '<span class="_eli3_er_diff_add">' + _esc(text) + '</span>';
      }
    });
    return html;
  }

  function _renderErrorCard(item, idx, onLocate, onAcceptOne) {
    var card = document.createElement("div");
    card.className = "_eli3_er_card slide-in";
    card.style.animationDelay = (idx * 0.05) + "s";
    card.setAttribute("data-error-idx", String(idx));

    var typeLabel = item.error_type || "Suggestion";
    var typeIcon = "📝";
    var diffHtml = _renderDiff(item.original || "", item.correction || "");

    card.innerHTML =
      '<div class="_eli3_er_tab">' + typeIcon + " " + _esc(typeLabel) + '</div>' +
      '<div class="_eli3_er_card_body">' +
        '<div class="_eli3_er_diff_block">' + diffHtml + '</div>' +
        (item.reason
          ? '<div class="_eli3_er_card_reason">' + _esc(item.reason) + '</div>'
          : ''
        ) +
      '</div>' +
      '<div class="_eli3_er_card_actions">' +
        '<button class="_eli3_er_btn _eli3_er_btn_secondary _eli3_er_btn_locate">📍 Locate</button>' +
        '<button class="_eli3_er_btn _eli3_er_btn_primary _eli3_er_btn_accept">✓ Accept Fix</button>' +
        '<button class="_eli3_er_btn _eli3_er_btn_secondary _eli3_er_btn_ignore">Skip</button>' +
      '</div>' +
      '<div class="_eli3_er_card_status _eli3_er_card_status_pending"></div>';

    function _setStatus(text, kind) {
      var s = card.querySelector("._eli3_er_card_status");
      s.className = "_eli3_er_card_status _eli3_er_card_status_" + kind;
      s.textContent = text || "";
    }
    function _disableActions() {
      var btns = card.querySelectorAll("._eli3_er_card_actions button");
      Array.prototype.forEach.call(btns, function (b) { b.disabled = true; });
    }
    function _reenable() {
      var btns = card.querySelectorAll("._eli3_er_card_actions button");
      Array.prototype.forEach.call(btns, function (b) { b.disabled = false; });
    }

    card.querySelector("._eli3_er_btn_locate").onclick = function () {
      if (typeof onLocate !== "function") return;
      _setStatus("Locating…", "applying");
      Promise.resolve()
        .then(function () { return onLocate(item); })
        .then(function () { _setStatus("Located in document.", "located"); })
        .catch(function (err) {
          _setStatus("Couldn't locate: " + (err && err.message || "not found"), "failed");
        });
    };
    card.querySelector("._eli3_er_btn_accept").onclick = function () {
      if (typeof onAcceptOne !== "function") return;
      _disableActions();
      _setStatus("Applying fix…", "applying");
      Promise.resolve()
        .then(function () { return onAcceptOne(item); })
        .then(function () {
          _setStatus("Applied.", "applied");
          card.classList.add("_eli3_er_card_done");
        })
        .catch(function (err) {
          _reenable();
          _setStatus("Failed: " + (err && err.message || "unknown"), "failed");
        });
    };
    card.querySelector("._eli3_er_btn_ignore").onclick = function () {
      _disableActions();
      _setStatus("Skipped.", "ignored");
      card.classList.add("_eli3_er_card_done");
    };

    return card;
  }

  var result = (opts && opts.result) || {};
  var items = (result.items || []).slice();
  var onLocate = opts && opts.onLocate;
  var onAcceptOne = opts && opts.onAcceptOne;
  var mount = (opts && opts.mount) || document.getElementById("_eli3_dashboard_root");
  if (!mount) return;

  mount.innerHTML = "";
  var panel = document.createElement("div");
  panel.className = "_eli3_ds_panel";

  var headerSubtitle = items.length === 0
    ? "No fixes needed"
    : items.length + (items.length === 1 ? " fix found" : " fixes found");

  panel.innerHTML =
    '<div class="_eli3_ds_header">' +
      '<div class="_eli3_ds_header_eyebrow">PROOFREAD</div>' +
      '<div class="_eli3_ds_header_title"><span>🔍</span> Error Review · ' +
        _esc(headerSubtitle) +
      '</div>' +
    '</div>' +
    '<div class="_eli3_ds_body">' +
      (items.length === 0
        ? '<div class="_eli3_er_empty">' +
            '<div class="_eli3_er_empty_icon">✅</div>' +
            '<div class="_eli3_er_empty_title">No Errors Found</div>' +
            '<div class="_eli3_er_empty_desc">' +
              'Document body and footers passed all checks. Nice work.' +
            '</div>' +
          '</div>'
        : '<div id="_eli3_er_cards" class="_eli3_er_cards"></div>'
      ) +
    '</div>';
  mount.appendChild(panel);

  if (items.length > 0) {
    var cardsHost = panel.querySelector("#_eli3_er_cards");
    items.forEach(function (item, idx) {
      cardsHost.appendChild(_renderErrorCard(item, idx, onLocate, onAcceptOne));
    });
  }
}

jsonTools.init:
function init(eli) {
  var bundle = eli.tools._loaded["error_review"];
  if (!bundle) return;
  var analyze = bundle._eliEngineFns && bundle._eliEngineFns.analyze;
  var renderSettingsDialog = bundle._eliViewFns && bundle._eliViewFns.renderSettingsDialog;
  var renderProgressOverlay = bundle._eliViewFns && bundle._eliViewFns.renderProgressOverlay;
  var renderReportDialog = bundle._eliViewFns && bundle._eliViewFns.renderReportDialog;
  if (!analyze || !renderSettingsDialog || !renderProgressOverlay || !renderReportDialog) {
    eli.log.event("tool", "error_review_init_missing_fns", {
      analyze: !!analyze,
      settings: !!renderSettingsDialog,
      progress: !!renderProgressOverlay,
      report: !!renderReportDialog,
    });
    return;
  }

  // ── User-settings helpers (sensitivity persists across runs) ─────────
  function _readUserSettings() {
    try {
      var raw = eli.compat.lsGet("eli_user_settings");
      return raw ? JSON.parse(raw) : {};
    } catch (e) { return {}; }
  }
  function _writeUserSettings(s) {
    try { eli.compat.lsSet("eli_user_settings", JSON.stringify(s || {})); }
    catch (e) { /* noop */ }
  }

  // ── Pre-scan: detect selection ───────────────────────────────────────
  // If user has highlighted >5 chars, ask whether to scan just the
  // selection or the whole doc. Returns "selection" | "full" | null
  // (null = user cancelled). v2: askUserSelectionScope (line 17972).
  function _detectScope() {
    return eli.host.runRaw("error_review:check_selection", function (context) {
      var sel = context.document.getSelection();
      sel.load("text");
      return context.sync().then(function () {
        var text = (sel.text || "").trim();
        return text.length > 5 ? "askUser" : "full";
      });
    }).catch(function () { return "full"; });
  }
  function _askScope() {
    return new Promise(function (resolve) {
      showEliDialog({
        variant: "info",
        icon: "🧐",
        title: "Partial Selection",
        body:
          '<div style="font-size:12px;line-height:1.5">' +
          '<p>You highlighted specific text. What should ELI scan?</p>' +
          '</div>',
        buttons: [
          {
            label: "🎯 Selection Only",
            cls: "btn-action btn-secondary",
            onclick: function (e, ov) {
              if (ov.parentNode) ov.parentNode.removeChild(ov);
              resolve("selection");
            },
          },
          {
            label: "📄 Whole Document",
            cls: "btn-action btn-primary",
            onclick: function (e, ov) {
              if (ov.parentNode) ov.parentNode.removeChild(ov);
              resolve("full");
            },
          },
          {
            label: "Cancel",
            cls: "btn-action btn-secondary",
            onclick: function (e, ov) {
              if (ov.parentNode) ov.parentNode.removeChild(ov);
              resolve(null);
            },
          },
        ],
      });
    });
  }

  // ── Pre-scan: detect redlines ────────────────────────────────────────
  // v2: checkRedlinesBeforeScan (line 6220). Returns true to proceed,
  // false to cancel. If no redlines, resolves immediately to true.
  function _checkRedlines() {
    return eli.host.runRaw("error_review:check_redlines", function (context) {
      var c = context.document.body.getTrackedChanges();
      c.load("items");
      return context.sync().then(function () {
        return c.items && c.items.length > 0;
      });
    }).catch(function () { return false; }).then(function (hasRedlines) {
      if (!hasRedlines) return true;
      return new Promise(function (resolve) {
        showEliDialog({
          variant: "warning",
          icon: "⚡",
          title: "Redlines Detected",
          body:
            '<div style="font-size:12px;line-height:1.5">' +
            '<p>Heavy redlines can interfere with AI. Recommended: cancel, switch ' +
            'Word to <b>No Markup</b>, then re-scan.</p>' +
            '</div>',
          buttons: [
            {
              label: "Cancel",
              cls: "btn-action btn-secondary",
              onclick: function (e, ov) {
                if (ov.parentNode) ov.parentNode.removeChild(ov);
                resolve(false);
              },
            },
            {
              label: "Proceed Anyway",
              cls: "btn-action btn-danger",
              onclick: function (e, ov) {
                if (ov.parentNode) ov.parentNode.removeChild(ov);
                resolve(true);
              },
            },
          ],
        });
      });
    });
  }

  // ── Locate handler ──────────────────────────────────────────────────
  function _locate(item) {
    return eli.host.runRaw("error_review:locate", function (context) {
      var bookmarkName = item && item.id;
      var hasBookmarkId = bookmarkName && /^_ELI_ER_\d+$/.test(bookmarkName);
      if (hasBookmarkId) {
        var bks = context.document.body.getRange().bookmarks;
        bks.load("items");
        return context.sync().then(function () {
          var match = bks.items.filter(function (b) { return b && b.name === bookmarkName; })[0];
          if (match) {
            var bRange = match.getRange();
            var phrase = (item.original || "").trim();
            if (phrase.length > 1) {
              var sr = bRange.search(phrase, { matchCase: false, matchWholeWord: false });
              sr.load("items");
              return context.sync().then(function () {
                if (sr.items.length > 0) sr.items[0].select();
                else bRange.select();
                return context.sync();
              });
            }
            bRange.select();
            return context.sync();
          }
          return _bodySearchSelect(context, item.original);
        });
      }
      return _bodySearchSelect(context, item.original);
    });
  }
  function _bodySearchSelect(context, phrase) {
    if (!phrase) {
      throw new (window.eli && window.eli.errors && window.eli.errors.ToolError || Error)("Nothing to locate.");
    }
    var sr = context.document.body.search(phrase, { matchCase: false, matchWholeWord: false });
    sr.load("items");
    return context.sync().then(function () {
      if (sr.items.length === 0) {
        throw new (window.eli && window.eli.errors && window.eli.errors.ToolError || Error)("Not found: " + phrase);
      }
      sr.items[0].select();
      return context.sync();
    });
  }

  // ── Accept handler ──────────────────────────────────────────────────
  function _acceptOne(item) {
    return eli.host.runRaw("error_review:accept", function (context) {
      var phrase = (item.original || "").trim();
      var fix = item.correction || "";
      if (!phrase) {
        throw new (window.eli && window.eli.errors && window.eli.errors.ToolError || Error)("Empty 'original' — can't replace.");
      }
      var bookmarkName = item && item.id;
      var hasBookmarkId = bookmarkName && /^_ELI_ER_\d+$/.test(bookmarkName);
      if (hasBookmarkId) {
        var bks = context.document.body.getRange().bookmarks;
        bks.load("items");
        return context.sync().then(function () {
          var match = bks.items.filter(function (b) { return b && b.name === bookmarkName; })[0];
          if (match) {
            var sr = match.getRange().search(phrase, { matchCase: false, matchWholeWord: false });
            sr.load("items");
            return context.sync().then(function () {
              if (sr.items.length > 0) {
                sr.items[0].insertText(fix, "Replace");
                return context.sync();
              }
              return _bodySearchReplace(context, phrase, fix);
            });
          }
          return _bodySearchReplace(context, phrase, fix);
        });
      }
      return _bodySearchReplace(context, phrase, fix);
    });
  }
  function _bodySearchReplace(context, phrase, fix) {
    var sr = context.document.body.search(phrase, { matchCase: false, matchWholeWord: false });
    sr.load("items");
    return context.sync().then(function () {
      if (sr.items.length === 0) {
        throw new (window.eli && window.eli.errors && window.eli.errors.ToolError || Error)("Couldn't find '" + phrase + "' in document.");
      }
      sr.items[0].insertText(fix, "Replace");
      return context.sync();
    });
  }

  // ── Scan flow ────────────────────────────────────────────────────────
  function _runScan(settings) {
    var mount = document.getElementById("_eli3_dashboard_root");

    function _safeTransition(target) {
      try { eli.fsm.transition(target); }
      catch (e) { /* tolerate */ }
    }
    function _goHome() {
      if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
      else if (eli.dashboard && eli.dashboard.refresh) eli.dashboard.refresh();
    }

    _safeTransition("scanning");
    var overlay = renderProgressOverlay();
    var providers = { host: eli.host, ai: eli.ai, storage: eli.storage };
    var input = { settings: settings, onLog: overlay.log, docHash: null };

    function _afterAnalyze(result) {
      try {
        if (eli.stats) {
          eli.stats.record("appOpenedError");
          eli.stats.record("docsReviewed");
          eli.stats.record("errorsScanned");
          if (result.items && result.items.length) {
            eli.stats.record("errorsFound", result.items.length);
          }
        }
        if (eli.activity) {
          var summary = result.items.length === 0
            ? "✅ No errors found"
            : result.items.length + " issue(s) detected";
          eli.activity.add({
            type: "error_review",
            icon: "🔍",
            label: "Error Review",
            summary: summary,
          });
        }
        if (eli.wrongness) eli.wrongness.capture("error_review", input, result, {});
      } catch (sideErr) {
        eli.log.event("tool", "error_review_side_effects_failed", {
          error: sideErr && sideErr.message,
        });
      }
      _safeTransition("rendering");
      renderReportDialog({
        result: result,
        mount: mount,
        onLocate: _locate,
        onAcceptOne: _acceptOne,
        onClose: function () {
          _safeTransition("idle");
          _goHome();
        },
      });
    }

    analyze(input, providers).then(function (result) {
      overlay.close();
      try {
        _afterAnalyze(result);
      } catch (renderErr) {
        eli.log.event("tool", "error_review_render_failed", {
          error: renderErr && renderErr.message,
          stack: (renderErr && renderErr.stack || "").slice(0, 500),
        });
        if (typeof showToast === "function") {
          showToast("Report render failed: " + (renderErr && renderErr.message || "unknown"), "err");
        }
        _goHome();
        _safeTransition("error");
        setTimeout(function () { try { eli.fsm.transition("idle"); } catch (e) {} }, 100);
      }
    }).catch(function (err) {
      overlay.close();
      _goHome();
      _safeTransition("error");
      if (typeof showToast === "function") {
        showToast("Scan failed: " + (err && err.message || "unknown"), "err");
      }
      eli.log.event("tool", "error_review_failed", { error: err && err.message });
      setTimeout(function () { try { eli.fsm.transition("idle"); } catch (e) {} }, 100);
    });
  }

  // ── Tile handler (main click) ────────────────────────────────────────
  // Direct path: API-key check → redlines warn → scope detect → scan.
  // No settings dialog. Settings live behind the gear icon.
  function tileHandler() {
    if (!eli.ai || !eli.ai.hasApiKey()) {
      if (typeof showToast === "function") {
        showToast("Set a Gemini API key in Settings → Global first.", "warn");
      }
      // Open settings as a courtesy so the user can fix it.
      if (eli.settings && eli.settings.show) eli.settings.show();
      return;
    }

    var saved = _readUserSettings();
    var sensitivity = saved.sensitivity || "Balanced";

    // Pre-scan: redlines warning, then selection-scope decision.
    _checkRedlines().then(function (proceed) {
      if (!proceed) return;
      _detectScope().then(function (initial) {
        if (initial === "askUser") {
          _askScope().then(function (scope) {
            if (!scope) return; // user cancelled
            _runScan({ sensitivity: sensitivity, scope: scope });
          });
        } else {
          _runScan({ sensitivity: sensitivity, scope: "full" });
        }
      });
    });
  }

  // ── Gear handler (settings) ──────────────────────────────────────────
  // Opens the sensitivity picker. Settings persist on Save (closing the
  // dialog with Save). Cancel just dismisses.
  function gearHandler() {
    var saved = _readUserSettings();
    var hasApiKey = !!(eli.ai && eli.ai.hasApiKey());
    var mount = document.getElementById("_eli3_dashboard_root");
    renderSettingsDialog({
      hasApiKey: hasApiKey,
      sensitivity: saved.sensitivity || "Balanced",
      mount: mount,
      gearMode: true, // tells the view to render Save/Cancel instead of Scan/Home
    }).then(function (settings) {
      if (settings) {
        var s = _readUserSettings();
        s.sensitivity = settings.sensitivity;
        _writeUserSettings(s);
        if (typeof showToast === "function") {
          showToast("Saved: sensitivity " + settings.sensitivity, "ok");
        }
      }
      if (eli.dashboard && eli.dashboard.goHome) eli.dashboard.goHome();
    });
  }

  // Register both channels.
  eli.register({
    tile: { "app_error_review": tileHandler },
    tile_settings: { "app_error_review": gearHandler },
  });
  eli.log.event("tool", "error_review_initialized", {});
}
